// @ts-check
// Generated by `elm-watch init --javascript`. It’s yours now – change it
// however you like!
// Documentation: https://lydell.github.io/elm-watch/javascript-api/
//
// Usage (target names are matched by substring, like the elm-watch command):
//
//     node --watch elm-watch.mjs hot [target names...]
//     node elm-watch.mjs make [--debug|--optimize] [target names...]

import { exec } from "node:child_process";
import { parseArgs, promisify } from "node:util";
import { elmWatch } from "elm-watch";

const { positionals, values } = parseArgs({
  allowPositionals: true,
  options: {
    debug: { type: "boolean", default: false },
    optimize: { type: "boolean", default: false },
  },
});

const [runMode = "hot", ...targetNames] = positionals;

if (runMode !== "hot" && runMode !== "make") {
  console.error(`Expected "hot" or "make", but got: ${runMode}`);
  process.exit(1);
}

/** @type {Array<import("elm-watch").Target>} */
const targets = [
  {
    type: "application",
    name: "Main",
    elmJson: "elm.json",
    inputs: ["src/Main.elm"],
    output: "build/main.js",
  },
];

const enabledTargets = targets.filter(
  (target) =>
    targetNames.length === 0 ||
    targetNames.some((targetName) => target.name.includes(targetName)),
);

if (enabledTargets.length === 0) {
  console.error(
    `No targets match: ${targetNames.join(", ")}\n\nAvailable targets:\n${targets.map((target) => target.name).join("\n")}`,
  );
  process.exit(1);
}

process.exitCode = await elmWatch({
  root: import.meta.dirname,
  runMode,
  compilationMode: values.optimize
    ? "optimize"
    : values.debug
      ? "debug"
      : "standard",
  targets: enabledTargets,
  // For example, ELM_WATCH_HOST=0.0.0.0 exposes the server on the local network.
  host: process.env.ELM_WATCH_HOST,
  staticFilesDir: ".",
  openEditor: openEditorFromEnv(),
});

// Opens error locations that you click in the browser UI in your editor.
// Each developer can choose their editor by setting the ELM_WATCH_OPEN_EDITOR
// environment variable, like with the elm-watch command:
// https://lydell.github.io/elm-watch/browser-ui/#clickable-error-locations
/** @returns {import("elm-watch").OpenEditor | undefined} */
function openEditorFromEnv() {
  const command = process.env.ELM_WATCH_OPEN_EDITOR;
  if (command === undefined) {
    return undefined;
  }
  const execAsync = promisify(exec);
  return async ({ file, line, column }) => {
    await execAsync(command, {
      cwd: import.meta.dirname,
      env: {
        ...process.env,
        file,
        line: line.toString(),
        column: column.toString(),
      },
      timeout: 5000,
    });
  };
}
